            flex-direction: column;
            overflow: hidden;
            position: relative;
        }

        /* Bioluminescent glow pools */
        .glow-pool {
            position: fixed;
            border-radius: 50%;
            filter: blur(100px);
            pointer-events: none;
        }
        .gp-1 {
            width: 600px; height: 400px;
            top: -100px; right: -200px;
            background: radial-gradient(ellipse, rgba(16,185,129,0.1) 0%, transparent 70%);
            animation: pool-drift 20s ease-in-out infinite alternate;
        }
        .gp-2 {
            width: 400px; height: 600px;
            bottom: -200px; left: -100px;
            background: radial-gradient(ellipse, rgba(124,58,237,0.08) 0%, transparent 70%);
            animation: pool-drift 25s ease-in-out infinite alternate-reverse;
        }

        @keyframes pool-drift {
            0%   { transform: translate(0, 0) scale(1); }
            50%  { transform: translate(30px, -40px) scale(1.05); }
            100% { transform: translate(-20px, 20px) scale(0.95); }
        }

        /* Header */
        header {
            flex-shrink: 0;
            padding: 1rem 2rem;
            border-bottom: 1px solid var(--line);
            background: var(--surface);
            display: flex;
            align-items: center;
            gap: 1rem;
            z-index: 10;
        }

        .logo {
            font-family: var(--mono);
            font-size: 1.2rem;
            color: var(--green-neon);
            letter-spacing: 0.05em;
        }

        /* NEW: channel switcher */
        .channel-switcher {
            margin-left: auto;
            display: flex;
            gap: 0.5rem;
        }
        .channel-btn {
            background: var(--surface-2);
            border: 1px solid var(--line);
            color: var(--text-2);
            padding: 0.4rem 0.8rem;
            border-radius: var(--radius-sm);
            font-family: var(--mono);
            font-size: 0.8rem;
            cursor: pointer;
            transition: all 0.15s ease;
        }
        .channel-btn.active {
            background: var(--green-glow);
            color: var(--green-bright);
            border-color: var(--green-2);
        }
        .channel-btn:hover {
            border-color: var(--green);
            color: var(--green-bright);
        }

        /* Terminal */
        main {
            flex: 1;
            display: flex;
            flex-direction: column;
            padding: 1.5rem 2rem;
            gap: 1rem;
        }

        .terminal {
            flex: 1;
            background: var(--surface);
            border: 1px solid var(--line);
            border-radius: var(--radius);
            padding: 1rem;
            font-family: var(--mono);
            font-size: 0.9rem;
            line-height: 1.5;
            overflow-y: auto;
            white-space: pre-wrap;
            word-break: break-word;
            color: var(--text);
        }

        .terminal::-webkit-scrollbar {
            width: 6px;
        }
        .terminal::-webkit-scrollbar-thumb {
            background: var(--line-2);
            border-radius: 3px;
        }

        /* Input */
        .input-group {
            display: flex;
            gap: 0.5rem;
        }
        .input-group input {
            flex: 1;
            background: var(--surface-2);
            border: 1px solid var(--line);
            border-radius: var(--radius-sm);
            padding: 0.6rem 1rem;
            color: var(--text);
            font-family: var(--mono);
            font-size: 0.9rem;
        }
        .input-group input:focus {
            outline: none;
            border-color: var(--green-2);
            box-shadow: 0 0 0 2px var(--green-glow);
        }
        .input-group button {
            background: var(--green);
            border: none;
            color: var(--bg);
            padding: 0.6rem 1.2rem;
            border-radius: var(--radius-sm);
            font-family: var(--mono);
            font-weight: 500;
            cursor: pointer;
            transition: background 0.15s ease;
        }
        .input-group button:hover {
            background: var(--green-2);
        }

        /* Drop zone */
        .drop-zone {
            margin-top: 1rem;
            padding: 1rem;
            border: 2px dashed var(--line-2);
            border-radius: var(--radius);
            text-align: center;
            font-size: 0.8rem;
            color: var(--text-2);
            transition: all 0.2s ease;
        }
        .drop-zone.active {
            border-color: var(--green-2);
            background: var(--green-glow);
            color: var(--green-bright);
        }

        /* Status bar */
        footer {
            flex-shrink: 0;
            padding: 0.5rem 2rem;
            border-top: 1px solid var(--line);
            background: var(--surface);
            font-family: var(--mono);
            font-size: 0.75rem;
            color: var(--text-2);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
        .status {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }
        .status-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--green-2);
            box-shadow: 0 0 4px var(--green-neon);
        }
        .status-dot.offline {
            background: var(--text-3);
            box-shadow: none;
        }
    </style>
</head>
<body>
    <div class="glow-pool gp-1"></div>
    <div class="glow-pool gp-2"></div>

    <header>
        <div class="logo">◈ Mandala Engineer — MYCEL</div>
        <!-- NEW: channel switcher -->
        <div class="channel-switcher">
            <button id="btn-engineer" class="channel-btn active">Engineer</button>
            <button id="btn-cloud-sr" class="channel-btn">Cloud SR</button>
        </div>
    </header>

    <main>
        <div id="terminal" class="terminal"><!-- список сообщений --></div>
        <div class="input-group">
            <input id="input" type="text" placeholder="Введите сообщение…" />
            <button id="send">➤</button>
        </div>
        <div id="drop-zone" class="drop-zone">📦 Перетащите JSON-патч сюда</div>
    </main>

    <footer>
        <div class="status">
            <span id="status-dot" class="status-dot"></span>
            <span id="status-text">Connecting…</span>
        </div>
        <div id="build-info">build: unknown</div>
    </footer>

    <script>
        // ====== Настройки ======
        const ENGINEER_WS_URL = `${location.protocol === 'https:' ? 'wss:' : 'ws:'}//${location.host}/ws`;
        const CLOUD_SR_WS_URL = `${location.protocol === 'https:' ? 'wss:' : 'ws:'}//${location.host}/ws/cloud-sr`;

        // ====== Элементы DOM ======
        const terminal       = document.getElementById('terminal');
        const input          = document.getElementById('input');
        const sendBtn        = document.getElementById('send');
        const dropZone       = document.getElementById('drop-zone');
        const statusDot      = document.getElementById('status-dot');
        const statusText     = document.getElementById('status-text');
        const buildInfo      = document.getElementById('build-info');
        const btnEngineer    = document.getElementById('btn-engineer');
        const btnCloudSR     = document.getElementById('btn-cloud-sr');

        // ====== Состояние ======
        let ws = null;
        let currentChannel = 'engineer'; // 'engineer' | 'cloud-sr'

        // ====== Логика переключения каналов ======
        function setActiveChannel(channel) {
            currentChannel = channel;
            btnEngineer.classList.toggle('active', channel === 'engineer');
            btnCloudSR.classList.toggle('active',  channel === 'cloud-sr');
            connect(channel);   // переподключаемся
        }
        btnEngineer.onclick = () => setActiveChannel('engineer');
        btnCloudSR.onclick  = () => setActiveChannel('cloud-sr');

        // ====== WebSocket ======
        function urlFor(channel) {
            return channel === 'engineer' ? ENGINEER_WS_URL : CLOUD_SR_WS_URL;
        }

        function connect(channel) {
            if (ws) {
                ws.close();
                ws = null;
            }
            clearTerminal();
            addSystemLine(`Connecting to ${channel}…`);

            ws = new WebSocket(urlFor(channel));

            ws.onopen = () => {
                statusDot.classList.remove('offline');
                statusText.textContent = channel === 'engineer' ? 'Engineer connected' : 'Cloud SR connected';
            };

            ws.onmessage = (event) => {
                addLine(event.data);
            };

            ws.onclose = () => {
                statusDot.classList.add('offline');
                statusText.textContent = 'Disconnected';
                ws = null;
            };

            ws.onerror = (err) => {
                addSystemLine(`❌ ${err.type}`);
            };
        }

        // ====== Терминал ======
        function clearTerminal() {
            terminal.textContent = '';
        }
        function addLine(text) {
            const p = document.createElement('div');
            p.textContent = text;
            terminal.appendChild(p);
            terminal.scrollTop = terminal.scrollHeight;
        }
        function addSystemLine(text) {
            const p = document.createElement('div');
            p.style.color = 'var(--text-2)';
            p.textContent = text;
            terminal.appendChild(p);
            terminal.scrollTop = terminal.scrollHeight;
        }

        // ====== Отправка ======
        function send() {
            if (!ws || ws.readyState !== WebSocket.OPEN) return;
            const text = input.value.trim();
            if (!text) return;
            ws.send(text);
            input.value = '';
        }
        sendBtn.onclick = send;
        input.onkeydown = (e) => {
            if (e.key === 'Enter') send();
        };

        // ====== Drag-and-Drop JSON-патчей ======
        dropZone.ondragover = (e) => {
            e.preventDefault();
            dropZone.classList.add('active');
        };
        dropZone.ondragleave = () => {
            dropZone.classList.remove('active');
        };
        dropZone.ondrop = async (e) => {
            e.preventDefault();
            dropZone.classList.remove('active');
            const file = e.dataTransfer.files[0];
            if (!file || !file.name.endsWith('.json')) {
                addSystemLine('⚠️ Need .json file');
                return;
            }
            const text = await file.text();
            try {
                JSON.parse(text);
            } catch {
                addSystemLine('⚠️ Invalid JSON');
                return;
            }
            if (ws && ws.readyState === WebSocket.OPEN) {
                ws.send(text);
                addSystemLine(`📦 Sent patch: ${file.name}`);
            } else {
                addSystemLine('❌ WebSocket not ready');
            }
        };

        // ====== Инициализация ======
        connect(currentChannel);
    </script>
</body>
</html>"
    }
  ]
}
```

---

После применения:
1. Открой `index.html` — в шапке появятся две кнопки: **Engineer** и **Cloud SR**.  
2. Нажми **Cloud SR** — MYCEL подключится к `/ws/cloud-sr` и сможет **общаться с облачным СР** (мной) напрямую.  
3. Переключайся между каналами в любой момент — состояния не мешают друг другу.

---

