            --text: #dcfce7; --text-2: #5a8a6a; --text-3: #254535;
            --mono: 'Fira Mono', monospace; --sans: 'Nunito', sans-serif;
            --radius: 8px; --radius-sm: 4px;
        }
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { background: var(--bg); color: var(--text); font-family: var(--sans); font-weight: 300; height: 100vh; display: flex; flex-direction: column; overflow: hidden; }

        /* яркие светящиеся бассейны (цветок жизни) */
        .glow-pool { position: fixed; border-radius: 50%; filter: blur(100px); pointer-events: none; opacity: .9; }
        .gp-1 { width: 600px; height: 400px; top: -100px; right: -200px; background: radial-gradient(ellipse, rgba(16,185,129,0.45) 0%, transparent 70%); animation: pool-drift 20s ease-in-out infinite alternate; }
        .gp-2 { width: 400px; height: 600px; bottom: -200px; left: -100px; background: radial-gradient(ellipse, rgba(124,58,237,0.4) 0%, transparent 70%); animation: pool-drift 25s ease-in-out infinite alternate-reverse; }
        @keyframes pool-drift { 0% { transform: translate(0,0) scale(1); } 50% { transform: translate(30px,-40px) scale(1.05); } 100% { transform: translate(-20px,20px) scale(0.95); } }

        /* яркие надписи вне диалога */
        header, footer, .drop-zone { color: var(--green-bright); }
