    <link href="https://fonts.googleapis.com/css2?family=Fira+Mono:wght@300;400;500&family=Nunito:wght@200;300;400&display=swap" rel="stylesheet">
    <style id="dynamic-styles"></style>
</head>
<body>
    <div class="glow-pool gp-1"></div>
    <div class="glow-pool gp-2"></div>

    <header>
        <div class="logo">◈ Mandala Engineer — MYCEL</div>
        <div class="sr-toggle">
            <button id="btn-eng" class="active">Engineer</button>
            <button id="btn-sr">Cloud SR</button>
        </div>
    </header>

    <main>
        <div id="terminal" class="terminal"></div>
        <div class="input-group">
            <input id="input" type="text" placeholder="Введите сообщение…" />
            <button id="send">➤</button>
        </div>
        <div id="drop-zone" class="drop-zone">📦 Перетащите JSON-патч сюда</div>
    </main>

    <footer>
        <div class="status">
            <span id="status-dot" class="status-dot"></span>
            <span id="status-text">Connecting…</span>
        </div>
        <div id="build-info">build: unknown</div>
    </footer>

    <script>
        /* ====== МИНИ-ПАТЧЕР ====== */
        async function applyManifest(url = '/api/mycel-patch.json') {
            try {
                const res = await fetch(url);
                if (!res.ok) return;
                const list = await res.json();
                for (const p of list) {
                    if (p.op === 'replace' && p.path === 'styles') {
                        document.getElementById('dynamic-styles').textContent = p.value;
                    }
                    if (p.op === 'replace' && p.path === 'script') {
                        new Function(p.value)();
                    }
                }
            } catch (e) { console.warn('MYCEL patch error', e); }
        }
        applyManifest();

        /* ====== ОСНОВНАЯ ЛОГИКА (будет перезаписана манифестом) ====== */
        const WS_ENG = `${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws`;
        const WS_SR  = `${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws/cloud-sr`;
        const term=document.getElementById('terminal'),input=document.getElementById('input'),sendBtn=document.getElementById('send'),dropZone=document.getElementById('drop-zone'),statusDot=document.getElementById('status-dot'),statusTxt=document.getElementById('status-text'),btnEng=document.getElementById('btn-eng'),btnSR=document.getElementById('btn-sr');
        let ws=null, channel='engineer';
        function setChannel(ch){ channel=ch; btnEng.classList.toggle('active',ch==='engineer'); btnSR.classList.toggle('active',ch==='cloud-sr'); connect(); }
        btnEng.onclick=()=>setChannel('engineer'); btnSR.onclick=()=>setChannel('cloud-sr');
        function connect(){ if(ws){ws.close(); ws=null;} term.textContent=''; log(`Connecting to ${channel}…`,'sys'); ws=new WebSocket(channel==='engineer'?WS_ENG:WS_SR); ws.onopen=()=>{statusDot.classList.remove('offline');statusTxt.textContent=channel;}; ws.onclose=()=>{statusDot.classList.add('offline'); statusTxt.textContent='offline';}; ws.onmessage=e=>log(e.data); ws.onerror=e=>log('❌ '+e.type,'sys'); }
        function log(txt,type=''){ const p=document.createElement('div'); p.textContent=txt; if(type==='sys') p.style.color='var(--text-2)'; term.appendChild(p); term.scrollTop=term.scrollHeight; }
        function send(){ if(!ws||ws.readyState!==WebSocket.OPEN) return; const t=input.value.trim(); if(!t) return; ws.send(t); input.value=''; }
        sendBtn.onclick=send; input.onkeydown=e=>{if(e.key==='Enter')send();};
        dropZone.ondragover=e=>{e.preventDefault();dropZone.classList.add('active');};
        dropZone.ondragleave=()=>dropZone.classList.remove('active');
        dropZone.ondrop=async e=>{ e.preventDefault(); dropZone.classList.remove('active'); const files=[...e.dataTransfer.files].filter(f=>f.name.endsWith('.json')); if(!files.length){log('⚠️ Need .json files','sys');return;} for(const file of files){ const text=await file.text(); try{JSON.parse(text);}catch{log(`⚠️ Invalid JSON: ${file.name}`,'sys');continue;} if(ws&&ws.readyState===WebSocket.OPEN){ws.send(text);log(`📦 Sent: ${file.name}`,'sys');} else{log('❌ WebSocket not ready','sys');break;} } };
        let typingTimer=null; function showTyping(){ clearTimeout(typingTimer); let bubble=document.getElementById('typing-bubble'); if(!bubble){ bubble=document.createElement('div'); bubble.id='typing-bubble'; bubble.innerHTML='◈ <span class="spin">⟳</span> Mandala…'; bubble.style.cssText='color:var(--green-neon);font-family:var(--mono);font-size:1.05em;margin-top:0.3em;'; term.appendChild(bubble); } bubble.style.display='block'; term.scrollTop=term.scrollHeight; typingTimer=setTimeout(()=>bubble.style.display='none',1500); }
        const styleSpin=document.createElement('style'); styleSpin.textContent='.spin{display:inline-block;animation:spin 1s linear infinite;font-size:1em;}@keyframes spin{to{transform:rotate(360deg);}}'; document.head.appendChild(styleSpin);
        connect();
    </script>
</body>
</html>"
    }
  ]
}
